export const FABRIC_CATEGORIES = FABRICS.map((c) => c.category)
export const familiesOf = (category: string): FabricFamily[] =>
  FABRICS.find((c) => c.category === category)?.families ?? []
export const colorsOf = (category: string, family: string): FabricColor[] =>
  familiesOf(category).find((f) => f.family === family)?.colors ?? []
export const findFabric = (name: string): FabricColor | null => {
  for (const c of FABRICS) for (const f of c.families) { const hit = f.colors.find((x) => x.name === name); if (hit) return hit }
  return null
}

